WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_doc_comment'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '评论短评类', 'kp-sl-doc-comment', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "评论短评类公文"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结构：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "表明态度，深度剖析。这就是一篇“微型综合分析题”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“短评”、“微评论”、“编者按”。针对某个具体的社会现象发表看法。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、答题骨架"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "引出话题并表态：一针见血地点评该现象（如：这一做法值得点赞 / 这一乱象令人深思）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "深度剖析：分析该现象背后的原因，或者它带来的深远影响（正反面结合）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "提出建议/升华：总结出普适性的规律，或者呼吁采取规范措施。"}]}]}]}]}$$ AS jsonb), NULL, '评论短评类的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "公文写作", "短评微评"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_doc_comment", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
